# -*- coding: utf-8 -*-
from parts import *
def ul(items,tag="ul"): return f'<{tag} role="list" class="c-list">'+''.join(f'<li class="c-list-item">{i}</li>' for i in items)+f'</{tag}>'
P=lambda t:f'<p class="c-p">{t}</p>'
H2=lambda t:f'<h2 class="c-art-h2">{t}</h2>'

APROPOS='<main class="c-main"><section class="c-page-hero"><div class="c-container">'+crumbs([("Accueil","/"),("À propos",None)])+'''<div class="c-hero-grid"><div><h1 class="c-h1-page">Valentin Turpin, fondateur de Connect</h1><p class="c-lead">J'ai créé Connect pour accompagner les dirigeants de TPE et PME dans leur développement commercial. Je travaille depuis Le Puy-Sainte-Réparade, dans le pays d'Aix, avec des clients à Aix-en-Provence, à Marseille et dans toute la région.</p><p class="c-p">Vous avez le même interlocuteur du premier échange à la mise en place.</p><a href="#contact" class="c-btn">Prendre contact</a></div><figure class="c-portrait"><div class="c-portrait-ph"><img src="/valentin.jpg" alt="Valentin Turpin, fondateur de Connect, assis à une table de café" class="c-portrait-img" width="896" height="1195" fetchpriority="high"></div></figure></div></div></section><section class="c-section"><div class="c-container"><div class="c-two-col"><div class="c-col"><p class="c-eyebrow">Mon parcours</p><h2 class="c-h2">De la communication à la vente</h2></div><div class="c-col"><p class="c-p">J'ai commencé par des études de communication. J'y ai appris à construire un message, à choisir un canal, à penser une image de marque.</p><p class="c-p">Puis je suis passé de l'autre côté, dans la vente. Prospecter, décrocher des rendez-vous, défendre un devis face à un client qui compare. C'est là que j'ai vu ce qui manque à beaucoup d'entreprises : rarement des idées, presque toujours le lien entre le message et la signature.</p><p class="c-p">Connect est né de ce constat. J'y mets mes deux casquettes au service des TPE et PME : la communication pour être compris, la vente pour conclure. Et je reste sur le terrain, parce que c'est là qu'un plan commercial se vérifie.</p></div></div></div></section><section class="c-section"><div class="c-container"><h2 class="c-h2">Ma façon de travailler</h2><div class="c-principles"><div class="c-principle"><h3 class="c-h3">Partir du terrain</h3><p class="c-p">Avant de recommander quoi que ce soit, je regarde comment vous vendez aujourd'hui : qui vous appelle, comment vous répondez, où les affaires se perdent.</p></div><div class="c-principle"><h3 class="c-h3">Vos outils d'abord</h3><p class="c-p">Je travaille avec ce que vous avez déjà. Un nouvel outil arrive seulement s'il vous fait gagner du temps.</p></div><div class="c-principle"><h3 class="c-h3">Peu d'actions, bien suivies</h3><p class="c-p">Deux ou trois chantiers menés jusqu'au bout valent mieux qu'un plan de vingt pages rangé dans un tiroir.</p></div></div></div></section><section class="c-section-alt"><div class="c-container"><h2 class="c-h2">Avec qui j'ai travaillé</h2><div class="c-grid-2"><div class="c-proof"><h3 class="c-h3">Fer de Lance Tattoo</h3><p class="c-proof-text">Studio de tatouage. Refonte du site et référencement local, avec une hausse d'environ 30 % du chiffre d'affaires constatée par la cliente.</p></div><div class="c-proof"><h3 class="c-h3">Insight to Sell</h3><p class="c-proof-text">Accompagnement sur le système d'acquisition. Avis Google de son dirigeant, Yoan Bouc : « nos résultats ont grandement progressé ».</p></div></div></div></section></main>'''+CONTACT

def legal(h1, body): return f'<main class="c-legal"><div class="c-container"><div class="c-legal-inner"><h1 class="c-h1-page">{h1}</h1>{body}</div></div></main>'
LH=lambda t:f'<h2 class="c-legal-h2">{t}</h2>'
MENTIONS=legal("Mentions légales",LH("Éditeur du site")+P("Le site connect-affaires.fr est édité par Valentin Turpin, entrepreneur individuel (micro-entreprise), exerçant sous le nom commercial Connect.")+P("SIREN : 932 479 702<br>SIRET : 932 479 702 00031<br>Code APE : 7022Z<br>Adresse : 127 boulevard Lucie Aubrac, 13610 Le Puy-Sainte-Réparade<br>Email : valentin@connect-affaires.fr")+P("TVA non applicable, article 293 B du Code général des impôts.")+LH("Directeur de la publication")+P("Valentin Turpin.")+LH("Hébergeur")+P("Vercel Inc.<br>440 N Barranca Avenue #4133, Covina, CA 91723, États-Unis<br>vercel.com")+LH("Propriété intellectuelle")+P("Les textes, photographies, logos et éléments graphiques de ce site appartiennent à Valentin Turpin, sauf mention contraire. Toute reproduction, même partielle, sans autorisation écrite préalable est interdite. Les noms et avis de clients sont publiés avec leur accord.")+LH("Données personnelles")+P('Le traitement des données transmises via le formulaire de contact est décrit dans la <a href="/politique-de-confidentialite" class="c-inline-link">politique de confidentialité</a>.'))
CONFID=legal("Politique de confidentialité",P("Cette page explique quelles données je collecte sur connect-affaires.fr, pourquoi, et comment exercer vos droits.")+LH("Responsable du traitement")+P("Valentin Turpin, entrepreneur individuel exerçant sous le nom Connect, 127 boulevard Lucie Aubrac, 13610 Le Puy-Sainte-Réparade. Contact : valentin@connect-affaires.fr.")+LH("Données collectées")+P("Via le formulaire de contact : nom, entreprise, adresse email, téléphone, type de besoin et message. Seuls le nom, l'email et le message sont obligatoires.")+LH("Utilisation")+P("Ces données servent uniquement à répondre à votre demande et, si une relation commerciale s'engage, à en assurer le suivi. Elles ne sont ni vendues, ni cédées, ni utilisées pour de la publicité. Le traitement repose sur votre consentement, donné en cochant la case du formulaire.")+LH("Durée de conservation")+P("Trois ans à compter du dernier échange, puis suppression.")+LH("Destinataires et hébergement")+P("Les demandes sont lues uniquement par moi. Google reçoit les statistiques de navigation si vous les acceptez (voir ci-dessous). Le site est hébergé par Vercel Inc., aux États-Unis. Les messages du formulaire sont transmis par le service Web3Forms, qui me les envoie par email. Ces deux prestataires agissent comme sous-traitants techniques.")+'<h2 class="c-legal-h2" id="cookies">Cookies et mesure d\'audience</h2>'+P("Le site utilise Google Analytics 4, un outil de mesure d'audience fourni par Google Ireland Limited, pour savoir quelles pages sont consultées et comment le site est utilisé. Ces cookies (_ga et _ga_*) ne sont déposés qu'après votre accord, donné dans le bandeau affiché lors de votre première visite. Sans accord, aucun cookie de mesure n'est déposé.")+P("Les données recueillies sont des statistiques de navigation (pages vues, durée, type d'appareil, provenance). Elles peuvent être transférées aux États-Unis ; Google adhère au Data Privacy Framework UE-États-Unis. Les cookies de mesure ont une durée de vie maximale de 13 mois et les données sont conservées 14 mois dans Google Analytics.")+P("Votre choix est enregistré dans votre navigateur pendant 6 mois. Vous pouvez le modifier à tout moment avec le lien « Cookies » en bas de chaque page. Le site n'utilise aucun cookie publicitaire.")+LH("Vos droits")+P("Vous pouvez demander à accéder à vos données, les corriger, les supprimer, en limiter l'usage, vous y opposer ou les récupérer, en écrivant à valentin@connect-affaires.fr. Vous pouvez aussi adresser une réclamation à la CNIL sur cnil.fr."))

def card(u,kind,t,txt,link): return f'<a href="{u}" class="c-card"><p class="c-card-num">{kind}</p><h2 class="c-h3">{t}</h2><p class="c-card-text">{txt}</p><p class="c-card-link">{link}</p></a>'
RESSOURCES='<main class="c-main"><section class="c-page-hero"><div class="c-container">'+crumbs([("Accueil","/"),("Ressources",None)])+'<div class="c-article-head"><h1 class="c-h1-page">Ressources commerciales et marketing BtoB</h1><p class="c-lead">Des guides courts et un cas client réel pour structurer votre développement commercial et votre marketing BtoB, à l\'échelle d\'une TPE ou d\'une PME.</p></div></div></section><section class="c-section"><div class="c-container"><div class="c-grid-3">'+card("/structurer-developpement-commercial-pme","Guide","Comment structurer le développement commercial d'une PME ?","Cible, offre, canaux, suivi des leads et indicateurs : une méthode en six étapes.","Lire le guide")+card("/marketing-btob-tpe-pme","Guide","Marketing BtoB : par où commencer en TPE ou PME ?","Objectif commercial, parcours du prospect, contenus utiles, conversion et mesure.","Lire le guide")+card("/cas-client-fer-de-lance","Cas client","Fer de Lance : plus de demandes de devis","Site, visibilité et acquisition pour un studio de tatouage, avec les résultats rapportés par la cliente.","Lire le cas client")+'</div></div></section></main>'

def article(crumb, eyebrow, h1, lead, meta, body, rel, btn=True):
    b='<a href="#contact" class="c-btn">Échanger sur vos enjeux</a>' if btn else ''
    return '<main class="c-main"><section class="c-page-hero"><div class="c-container">'+crumbs([("Accueil","/"),("Ressources","/ressources"),(crumb,None)])+f'<div class="c-article-head"><p class="c-eyebrow">{eyebrow}</p><h1 class="c-h1-page">{h1}</h1><p class="c-lead">{lead}</p><p class="c-article-meta">{meta}</p></div></div></section><section class="c-section"><div class="c-container"><article class="c-article">{body}{b}</article></div></section>'+related("À lire aussi",rel)+'</main>'+CONTACT
def enbref(t): return f'<div class="c-example"><p class="c-aside-title">En bref</p><p class="c-p">{t}</p></div>'

CAS=article("Cas client Fer de Lance","Cas client","Fer de Lance : mieux cibler, être mieux vu et recevoir plus de demandes","Retour sur une collaboration autour du site internet et de l'acquisition du studio de tatouage Fer de Lance (WUSE Tattoo), à partir du témoignage publié par la cliente sur Google.","Par Valentin Turpin, fondateur de Connect. Source des résultats : avis Google 5/5 de Fer de Lance, 2026.",
 '<div class="c-stats"><div class="c-stat"><p data-count="30" data-suffix="&nbsp;%" data-prefix="+" class="c-proof-kpi">+30&nbsp;%</p><p class="c-stat-label">de chiffre d\'affaires environ, selon la cliente</p></div><div class="c-stat"><p data-count="5" data-suffix="/5" class="c-proof-kpi">5/5</p><p class="c-stat-label">note de l\'avis Google laissé par la cliente</p></div></div>'
 +H2("Le contexte")+P("Avant son site, Fer de Lance communiquait surtout sur les réseaux sociaux, avec de la sponsorisation. D'après la cliente, cette approche lui apportait des abonnés, mais touchait moins bien les personnes prêtes à prendre rendez-vous.")
 +H2("Le travail mené")+P("Le site a été créé avec Insight to Sell et Connect. Le périmètre : un site et un dispositif pour mieux présenter l'activité, mieux orienter la visibilité et créer un parcours adapté aux demandes de devis.")+P("Mon rôle : relier le besoin commercial, le message, l'acquisition et les outils de conversion, au lieu de traiter chaque sujet séparément.")
 +H2("Les résultats rapportés par la cliente")+P("Dans son avis Google, Fer de Lance indique, depuis la mise en ligne du site en juin 2026 :")+ul(["une hausse d'environ 30 % de son chiffre d'affaires ;","de nombreuses demandes de devis chaque jour ;","un planning plus rempli sur le long terme."])+P("Ces résultats sont déclarés par la cliente. Ils dépendent de son activité et de son marché, et ne constituent pas une promesse de résultat.")
 +H2("Ce que ce cas montre")+P("On peut gagner en audience sans gagner en rendez-vous. La vraie question n'est pas combien de personnes voient la marque, mais si les bonnes personnes comprennent l'offre et savent quoi faire ensuite. Les actions qui ont compté :")+ul(["clarifier la cible et le positionnement ;","créer un support qui présente vraiment l'offre ;","orienter l'acquisition vers la bonne clientèle ;","faciliter la prise de contact ;","suivre les demandes reçues."],"ol")+P("L'avis complet est consultable sur la fiche Google de Connect."),
 [("Marketing BtoB à Aix-en-Provence","/marketing-btob-aix-en-provence"),("Acquisition BtoB","/acquisition-btob-aix-en-provence"),("Guide marketing BtoB","/marketing-btob-tpe-pme")],btn=False)

STRUCT=article("Structurer le développement commercial","Guide","Comment structurer le développement commercial d'une PME ?","Structurer son développement commercial, ce n'est pas multiplier les actions. C'est décider où concentrer l'effort, suivre les opportunités et relier le marketing aux objectifs de vente.","Par Valentin Turpin, fondateur de Connect. Publié le 30 septembre 2026.",
 enbref("Pour structurer le développement commercial d'une PME : définir une cible et une offre lisibles, choisir deux ou trois canaux d'acquisition, organiser le passage du lead à l'opportunité dans un CRM simple, découper les objectifs en activités suivies, puis ajuster le plan à partir des retours du terrain.")
 +H2("1. Commencer par une cible et une offre lisibles")+P("Avant la prospection, la publicité ou le CRM, il faut savoir quel type de client vous visez, quel problème vous résolvez et pourquoi on choisirait votre offre plutôt qu'une autre.")+P("Une cible trop large produit des messages génériques. Une offre mal expliquée pousse les commerciaux à improviser, chacun à sa façon.")
 +H2("2. Choisir quelques canaux d'acquisition")+P("Une PME gagne à se concentrer sur deux ou trois canaux adaptés à son marché :")+ul(["la prospection directe, quand les cibles sont identifiables ;","le référencement et la visibilité locale, quand les prospects cherchent déjà une solution ;","les contenus et les réseaux professionnels, pour construire la confiance dans la durée ;","le réseau, les partenariats et les recommandations, quand la relation fait la différence."])
 +H2("3. Organiser le passage du lead à l'opportunité")+P("C'est souvent entre le premier contact et la relance que tout se dégrade : qualification inégale, relances oubliées, prochaine action floue.")+P("Un CRM simple, avec quelques étapes cohérentes, rend plus de services qu'un outil complet que personne n'ouvre.")
 +H2("4. Transformer les objectifs en rythme de travail")+P("Un objectif annuel doit se découper en activités suivies régulièrement : opportunités créées, rendez-vous, propositions envoyées, affaires à relancer, taux de transformation. Le but n'est pas de tout mesurer, mais d'avoir assez d'informations pour décider.")
 +H2("5. Faire évoluer le plan à partir des retours")+P("La stratégie s'ajuste avec les objections des prospects, les canaux qui produisent vraiment et les étapes où les affaires ralentissent.")
 +H2("Une structure simple pour démarrer")+ul(["Définir les cibles prioritaires.","Clarifier l'offre et les arguments.","Choisir les principaux canaux d'acquisition.","Créer un pipeline de suivi.","Définir quelques indicateurs.","Faire un point régulier pour ajuster."],"ol")+P("Cette structure rend le développement commercial lisible sans alourdir l'organisation. Si vous voulez l'appliquer à votre entreprise, je peux vous aider à cadrer les priorités et à mettre en place les actions."),
 [("Conseil commercial","/conseil-commercial-aix-en-provence"),("CRM et organisation commerciale","/crm-organisation-commerciale-aix-en-provence"),("Guide marketing BtoB","/marketing-btob-tpe-pme"),("Cas client Fer de Lance","/cas-client-fer-de-lance")])

MKTG=article("Marketing BtoB pour TPE et PME","Guide","Marketing BtoB : par où commencer quand on est une TPE ou une PME ?","Sans méthode, le marketing BtoB se résume vite à des actions isolées : quelques publications, une campagne ponctuelle, un nouveau site, un outil de plus. Voici comment relier visibilité, acquisition et vente.","Par Valentin Turpin, fondateur de Connect. Publié le 30 septembre 2026.",
 enbref("Pour lancer le marketing BtoB d'une TPE ou d'une PME : partir de l'objectif commercial, comprendre comment le prospect décide, produire les contenus qui aident à vendre, améliorer la conversion avant d'augmenter le trafic, et suivre la qualité des leads plutôt que les seuls clics.")
 +H2("1. Partir de l'objectif commercial")+P("Le canal vient après l'objectif. Obtenir des rendez-vous avec des dirigeants locaux, développer une offre nationale ou faire connaître une expertise pointue ne demandent pas les mêmes actions. Commencez par définir ce que le marketing doit produire : des contacts, des demandes de devis, des inscriptions, des rendez-vous ou de la visibilité auprès d'une cible précise.")
 +H2("2. Comprendre comment le prospect décide")+P("En BtoB, le parcours s'étale souvent sur plusieurs jours : découverte sur Google ou LinkedIn, retour sur le site, lecture d'une ressource, puis prise de contact. Ce parcours doit rester cohérent, avec un message clair, des preuves suffisantes, un appel à l'action visible et un suivi rapide.")
 +H2("3. Choisir les contenus utiles au commerce")+ul(["Des pages services qui répondent aux questions clés avant le premier contact.","Des cas clients qui montrent comment un problème concret a été résolu.","Des guides qui traitent les questions que se posent vos prospects.","Des messages de campagne adaptés à la maturité de la cible."])
 +H2("4. Améliorer la conversion avant d'augmenter le trafic")+P("Envoyer plus de visiteurs vers une page mal construite rapporte rarement quelque chose de durable. Vérifiez d'abord la proposition de valeur, la lisibilité de l'offre, les preuves, le formulaire et les appels à l'action. Une landing page BtoB doit faire comprendre en quelques secondes ce que fait l'entreprise, pour qui, dans quel contexte, et quelle est l'étape suivante.")
 +H2("5. Suivre des indicateurs utiles")+P("Les impressions et les clics mesurent la visibilité, pas les ventes. Le pilotage passe aussi par la qualité des leads, leur origine, le taux de transformation et les opportunités réellement créées.")
 +H2("Par où commencer concrètement ?")+ul(["Définir la cible et l'objectif commercial.","Choisir un canal d'acquisition principal.","Créer ou améliorer la page de conversion associée.","Organiser le suivi commercial des leads.","Mesurer les résultats avant d'ajouter un nouveau canal."],"ol")+P("Avancer par étapes évite de disperser le budget et le temps de l'équipe. Je peux vous aider à cadrer ces priorités et à les mettre en place."),
 [("Marketing BtoB à Aix-en-Provence","/marketing-btob-aix-en-provence"),("Acquisition BtoB","/acquisition-btob-aix-en-provence"),("Structurer le développement commercial","/structurer-developpement-commercial-pme"),("Cas client Fer de Lance","/cas-client-fer-de-lance")])
